/** Injected stylesheet text — generated by scripts/copy-css.mjs. Do not edit. */
export const ZPGRAPH_CSS: string = "/**\n * @license\n * Copyright (c) 2026 João Vitor Zeppe (zeppejoaovitor@gmail.com)\n * MIT-licensed: https://opensource.org/license/MIT\n *\n * Portions derived from dygraphs — see NOTICE for upstream attribution.\n */\n\n/**\n * Default styles for the zpgraphs charting library.\n * Chrome colors/layout use CSS variables on `.zpgraph` so apps can theme\n * via `[data-theme=\"dark\"]` on an ancestor or on `.zpgraph` itself, or\n * override individual tokens. See README “DOM chrome tokens”.\n */\n\n.zpgraph {\n  /* legend (tooltip chrome) */\n  --zp-legend-bg: #ffffff;\n  --zp-legend-fg: #000000;\n  --zp-legend-shadow: none;\n  --zp-legend-padding: 0;\n  --zp-legend-radius: 0;\n  --zp-legend-font-size: 14px;\n  /* axis tick labels */\n  --zp-axis-label: #000000;\n  --zp-axis-label-font-size: inherit;\n  --zp-axis-label-opacity: 1;\n  --zp-axis-label-y-padding-end: 0;\n  /* chart title / x / y labels */\n  --zp-title-fg: inherit;\n  --zp-title-font-weight: bold;\n  --zp-chart-label-fg: inherit;\n  --zp-chart-label-opacity: 1;\n  /* annotations */\n  --zp-annotation-bg: #ffffff;\n  --zp-annotation-border: #000000;\n  --zp-annotation-fg: inherit;\n  --zp-annotation-padding: 2px 4px;\n  --zp-annotation-font-size: inherit;\n  /* focus */\n  --zp-focus-ring: #1a1a1a;\n  /* empty / loading overlay */\n  --zp-status-fg: #666666;\n  --zp-status-bg: rgba(255, 255, 255, 0.55);\n  --zp-status-font-size: 14px;\n  /* toolbar */\n  --zp-toolbar-bg: rgba(255, 255, 255, 0.92);\n  --zp-toolbar-fg: inherit;\n  --zp-toolbar-border: rgba(0, 0, 0, 0.12);\n  --zp-toolbar-border-width: 1px;\n  --zp-toolbar-radius: 4px;\n  --zp-toolbar-padding: 4px;\n  --zp-toolbar-gap: 4px;\n  --zp-toolbar-btn-bg: var(--zp-toolbar-bg);\n  --zp-toolbar-btn-fg: var(--zp-toolbar-fg);\n  --zp-toolbar-btn-border: var(--zp-toolbar-border);\n  --zp-toolbar-btn-border-width: 1px;\n  --zp-toolbar-btn-radius: 3px;\n  --zp-toolbar-btn-padding: 4px 8px;\n  --zp-toolbar-btn-font-size: 12px;\n  /* thresholds / extras labels */\n  --zp-threshold-fill: rgba(27, 107, 147, 0.14);\n  --zp-threshold-label-fg: #1b6b93;\n  --zp-threshold-label-font-size: 12px;\n  --zp-span-band-label-fg: #ffffff;\n  --zp-span-band-label-font-size: 11px;\n  --zp-span-band-label-padding: 2px 8px;\n  --zp-span-band-label-radius: 4px;\n  --zp-measure-label-bg: rgba(13, 27, 42, 0.85);\n  --zp-measure-label-fg: #ffffff;\n  --zp-measure-label-font-size: 12px;\n  --zp-measure-label-padding: 4px 8px;\n  --zp-measure-label-radius: 4px;\n}\n\n[data-theme=\"dark\"] .zpgraph,\n.zpgraph[data-theme=\"dark\"] {\n  --zp-legend-bg: #000000;\n  --zp-legend-fg: #ffffff;\n  --zp-legend-shadow: rgba(255, 255, 255, 0.4) 0 0 10px 1px;\n  --zp-axis-label: #e8e8e8;\n  --zp-title-fg: #e8e8e8;\n  --zp-chart-label-fg: #e8e8e8;\n  --zp-annotation-bg: #141414;\n  --zp-annotation-border: #434343;\n  --zp-annotation-fg: #e8e8e8;\n  --zp-focus-ring: #e8e8e8;\n  --zp-status-fg: #b0b0b0;\n  --zp-status-bg: rgba(0, 0, 0, 0.45);\n  --zp-toolbar-bg: rgba(20, 20, 20, 0.92);\n  --zp-toolbar-fg: #e8e8e8;\n  --zp-toolbar-border: rgba(255, 255, 255, 0.16);\n  --zp-threshold-label-fg: #7ec8e3;\n  --zp-measure-label-bg: rgba(0, 0, 0, 0.85);\n}\n\n.zpgraph:focus {\n  outline: none;\n}\n\n.zpgraph:focus-visible {\n  outline: 2px solid var(--zp-focus-ring);\n  outline-offset: 2px;\n}\n\n.zpgraph-legend {\n  position: absolute;\n  font-size: var(--zp-legend-font-size);\n  z-index: 10;\n  width: 250px; /* labelsDivWidth */\n  /*\n  zpgraphs determines these based on the presence of chart labels.\n  It might make more sense to create a wrapper div around the chart proper.\n  top: 0px;\n  right: 2px;\n  */\n  padding: var(--zp-legend-padding);\n  border-radius: var(--zp-legend-radius);\n  background: var(--zp-legend-bg);\n  color: var(--zp-legend-fg);\n  box-shadow: var(--zp-legend-shadow);\n  line-height: normal;\n  text-align: left;\n  overflow: hidden;\n}\n\n.zpgraph-legend[dir=\"rtl\"] {\n  text-align: right;\n}\n\n/* styles for a solid line in the legend */\n.zpgraph-legend-line {\n  display: inline-block;\n  position: relative;\n  bottom: 0.5ex;\n  padding-left: 1em;\n  height: 1px;\n  border-bottom-width: 2px;\n  border-bottom-style: solid;\n  /* border-bottom-color is set based on the series color */\n}\n\n/* styles for a dashed line in the legend, e.g. when strokePattern is set */\n.zpgraph-legend-dash {\n  display: inline-block;\n  position: relative;\n  bottom: 0.5ex;\n  height: 1px;\n  border-bottom-width: 2px;\n  border-bottom-style: solid;\n  /* border-bottom-color is set based on the series color */\n  /* margin-right is set based on the stroke pattern */\n  /* padding-left is set based on the stroke pattern */\n}\n\n.zpgraph-roller {\n  position: absolute;\n  z-index: 10;\n}\n\n/* This class is shared by all annotations, including those with icons */\n.zpgraph-annotation {\n  position: absolute;\n  z-index: 10;\n  overflow: hidden;\n  color: var(--zp-annotation-fg);\n  font-size: var(--zp-annotation-font-size);\n}\n\n/* This class only applies to annotations without icons */\n/* Old class name: .zpgraphDefaultAnnotation */\n.zpgraph-default-annotation {\n  border: 1px solid var(--zp-annotation-border);\n  background-color: var(--zp-annotation-bg);\n  padding: var(--zp-annotation-padding);\n  text-align: center;\n}\n\n.zpgraph-axis-label {\n  /* position: absolute; */\n  z-index: 10;\n  line-height: normal;\n  overflow: hidden;\n  color: var(--zp-axis-label);\n  font-size: var(--zp-axis-label-font-size);\n  opacity: var(--zp-axis-label-opacity);\n}\n\n.zpgraph-axis-label-y {\n  padding-right: var(--zp-axis-label-y-padding-end);\n}\n\n.zpgraph-title {\n  font-weight: var(--zp-title-font-weight);\n  color: var(--zp-title-fg);\n  z-index: 10;\n  text-align: center;\n  /* font-size: based on titleHeight option */\n}\n\n.zpgraph-xlabel,\n.zpgraph-ylabel,\n.zpgraph-y2label {\n  color: var(--zp-chart-label-fg);\n  opacity: var(--zp-chart-label-opacity);\n}\n\n.zpgraph-xlabel {\n  text-align: center;\n  /* font-size: based on xLabelHeight option */\n}\n\n/* For y-axis label */\n.zpgraph-label-rotate-left {\n  text-align: center;\n  transform: rotate(90deg);\n}\n\n/* For y2-axis label */\n.zpgraph-label-rotate-right {\n  text-align: center;\n  transform: rotate(-90deg);\n}\n\n.zpgraph-toolbar {\n  position: absolute;\n  z-index: 20;\n  display: flex;\n  flex-wrap: wrap;\n  gap: var(--zp-toolbar-gap);\n  padding: var(--zp-toolbar-padding);\n  background: var(--zp-toolbar-bg);\n  color: var(--zp-toolbar-fg);\n  border: var(--zp-toolbar-border-width) solid var(--zp-toolbar-border);\n  border-radius: var(--zp-toolbar-radius);\n  box-sizing: border-box;\n}\n\n.zpgraph-toolbar-top-right {\n  top: 4px;\n  right: 8px;\n}\n\n.zpgraph-toolbar-top-left {\n  top: 4px;\n  left: 8px;\n}\n\n/* Explicit button chrome — survives Ant Design / Tailwind resets. */\n.zpgraph-toolbar .zpgraph-toolbar-btn {\n  all: unset;\n  box-sizing: border-box;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 4px;\n  font-family: inherit;\n  font-size: var(--zp-toolbar-btn-font-size);\n  line-height: 1.2;\n  padding: var(--zp-toolbar-btn-padding);\n  margin: 0;\n  cursor: pointer;\n  border: var(--zp-toolbar-btn-border-width) solid var(--zp-toolbar-btn-border);\n  border-radius: var(--zp-toolbar-btn-radius);\n  background: var(--zp-toolbar-btn-bg);\n  color: var(--zp-toolbar-btn-fg);\n  white-space: nowrap;\n}\n\n.zpgraph-toolbar .zpgraph-toolbar-btn svg {\n  display: block;\n  flex: 0 0 auto;\n}\n\n.zpgraph-toolbar .zpgraph-toolbar-btn.is-active {\n  font-weight: 600;\n  outline: 1px solid currentColor;\n}\n\n.zpgraph-sr-only {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  padding: 0;\n  margin: -1px;\n  overflow: hidden;\n  clip: rect(0, 0, 0, 0);\n  white-space: nowrap;\n  border: 0;\n}\n\n.zpgraph-status {\n  position: absolute;\n  inset: 0;\n  z-index: 15;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  color: var(--zp-status-fg);\n  background: var(--zp-status-bg);\n  pointer-events: none;\n  font-size: var(--zp-status-font-size);\n}\n\n.zpgraph-threshold-label {\n  color: var(--zp-threshold-label-fg);\n  font-size: var(--zp-threshold-label-font-size);\n  font-family: inherit;\n  line-height: 1.2;\n  white-space: nowrap;\n}\n\n.zpgraph-span-band-label {\n  color: var(--zp-span-band-label-fg);\n  font-size: var(--zp-span-band-label-font-size);\n  font-family: inherit;\n  line-height: 1.2;\n  padding: var(--zp-span-band-label-padding);\n  border-radius: var(--zp-span-band-label-radius);\n  white-space: nowrap;\n}\n\n.zpgraph-measure-label {\n  background: var(--zp-measure-label-bg);\n  color: var(--zp-measure-label-fg);\n  font-size: var(--zp-measure-label-font-size);\n  font-family: inherit;\n  padding: var(--zp-measure-label-padding);\n  border-radius: var(--zp-measure-label-radius);\n}\n";
